window.MOVA_PATH={"kids":{"Pre-A1":{"name":"Starter","adv":0,"topics":[{"id":"k-pre-a1-1","t":"Hello! My name is…","s":"Saludos y presentarse"},{"id":"k-pre-a1-2","t":"Colors","s":"red, blue, yellow…"},{"id":"k-pre-a1-3","t":"Numbers 1–10","s":"one, two, three…"},{"id":"k-pre-a1-4","t":"It is…","s":"It is a cat"},{"id":"k-pre-a1-5","t":"I like / I don't like","s":"I like apples"},{"id":"k-pre-a1-6","t":"My body","s":"head, hands, feet"}],"writing":[],"phonics":[],"vocab":[]},"A1":{"name":"Beginner","adv":0,"topics":[{"id":"k-a1-1","t":"I am, you are, it is","s":"Verb to be","exp":["Usamos <b>am, is, are</b> para decir quién es alguien o cómo es.","<b>I</b> → am","<b>He, She, It</b> → is","<b>You, We, They</b> → are"],"ex":[["I am happy.","Yo estoy feliz."],["She is my sister.","Ella es mi hermana."],["It is a cat.","Es un gato."],["We are friends.","Somos amigos."]],"b":["I am seven years old.","She is my teacher.","They are in the park.","It is a big dog."],"q":[["I ___ a student.",["am","is","are","be"],0,"Con I usamos am."],["My mom ___ nice.",["am","is","are","be"],1,"Mom = she, y con she usamos is."],["We ___ friends.",["am","is","are","be"],2,"Con we usamos are."],["The dog ___ brown.",["am","is","are","be"],1,"The dog = it, y con it usamos is."],["You ___ tall.",["am","is","are","be"],2,"Con you usamos are."],["My shoes ___ new.",["am","is","are","be"],2,"Shoes son varios (they), entonces are."]]},{"id":"k-a1-2","t":"Is it…? Yes, it is.","s":"Preguntas con to be","exp":["Para preguntar, ponemos <b>is, are, am</b> al principio.","It is a cat. → <b>Is it</b> a cat?","Respondemos: <b>Yes, it is.</b> / <b>No, it isn't.</b>"],"ex":[["Is it a ball? Yes, it is.","¿Es una pelota? Sí."],["Is she your friend? Yes, she is.","¿Es tu amiga? Sí."],["Are they cats? No, they aren't.","¿Son gatos? No."],["Are you hungry? Yes, I am.","¿Tienes hambre? Sí."]],"b":["Is it a book?","Are you sad?","Is he your brother?","Are they in the garden?"],"q":[["___ it a pencil? Yes, it is.",["Is","Are","Am","Do"],0,"Con it usamos is."],["Are you happy? Yes, I ___.",["am","is","are","do"],0,"Con I usamos am."],["Is it a dog? No, it ___.",["isn't","aren't","am not","don't"],0,"It is → it isn't."],["___ they your shoes?",["Are","Is","Am","Does"],0,"Con they usamos are."],["Is Ana your sister? Yes, ___ is.",["she","he","it","they"],0,"Ana es niña: she."],["Are we late? No, we ___.",["aren't","isn't","am not","don't"],0,"We are → we aren't."]]},{"id":"k-a1-3","t":"I have, she has","s":"Have / Has","exp":["Usamos <b>have</b> con I, you, we, they.","Usamos <b>has</b> con he, she, it.","Para decir que no tenemos algo: <b>I don't have</b>."],"ex":[["I have a blue bike.","Tengo una bici azul."],["She has two cats.","Ella tiene dos gatos."],["We have art today.","Hoy tenemos arte."],["I don't have a pencil.","No tengo lápiz."]],"b":["I have a little brother.","He has a green backpack.","We have a big house.","I don't have a dog."],"q":[["She ___ long hair.",["has","have","is","are"],0,"Con she usamos has."],["I ___ two eyes.",["have","has","am","is"],0,"Con I usamos have."],["My cat ___ a long tail.",["has","have","is","are"],0,"My cat = it: has."],["They ___ a new car.",["have","has","are","is"],0,"Con they usamos have."],["I ___ have a pet.",["don't","doesn't","am not","no"],0,"Con I usamos don't."],["Tom ___ a red cap.",["has","have","is","are"],0,"Tom = he: has."]]},{"id":"k-a1-4","t":"This, that, these, those","s":"Cerca y lejos","exp":["<b>this</b> = esto (cerca, uno)","<b>that</b> = eso (lejos, uno)","<b>these</b> = estos (cerca, varios)","<b>those</b> = esos (lejos, varios)"],"ex":[["This is my book.","Este es mi libro."],["That is your chair.","Esa es tu silla."],["These are my shoes.","Estos son mis zapatos."],["Those are birds.","Esos son pájaros."]],"b":["This is my pencil.","That is a big tree.","These are my friends.","Those are your toys."],"q":[["(cerca) ___ is my hat.",["This","These","Those","They"],0,"Cerca y uno: this."],["(lejos, varios) ___ are stars.",["Those","That","This","These"],0,"Lejos y varios: those."],["(cerca, varios) ___ are my crayons.",["These","This","That","Those"],0,"Cerca y varios: these."],["(lejos) ___ is the moon.",["That","This","These","Those"],0,"Lejos y uno: that."],["This ___ my mom.",["is","are","am","be"],0,"This va con is."],["These ___ apples.",["are","is","am","be"],0,"These va con are."]]},{"id":"k-a1-5","t":"One dog, two dogs","s":"Plurales","exp":["Para hablar de más de uno, agregamos <b>-s</b>: cat → cats.","Si termina en s, sh, ch o x, agregamos <b>-es</b>: box → boxes.","Algunas palabras cambian: child → <b>children</b>, foot → <b>feet</b>, mouse → <b>mice</b>."],"ex":[["I have two cats.","Tengo dos gatos."],["There are three boxes.","Hay tres cajas."],["The children are playing.","Los niños están jugando."],["I have two feet.","Tengo dos pies."]],"b":["I have three red apples.","The boxes are big.","I see two birds.","The children are happy."],"q":[["one book, two ___",["books","bookes","book","bookies"],0,"Solo agregamos -s."],["one box, two ___",["boxes","boxs","box","boxies"],0,"Termina en x: -es."],["one child, three ___",["children","childs","childes","child"],0,"Child cambia a children."],["one bus, two ___",["buses","buss","bus","busies"],0,"Termina en s: -es."],["one foot, two ___",["feet","foots","feets","footes"],0,"Foot cambia a feet."],["one mouse, two ___",["mice","mouses","mices","mouse"],0,"Mouse cambia a mice."]]},{"id":"k-a1-6","t":"I can, I can't","s":"Habilidades","exp":["<b>can</b> = puede o sabe hacer algo.","<b>can't</b> = no puede.","Después de can, el verbo no cambia: She can <b>swim</b> (no swims)."],"ex":[["I can jump.","Puedo saltar."],["Fish can swim.","Los peces pueden nadar."],["Birds can fly.","Los pájaros pueden volar."],["I can't ride a horse.","No puedo montar a caballo."]],"b":["I can ride a bike.","My dog can run fast.","Penguins can't fly.","Can you sing?"],"q":[["She can ___.",["swim","swims","swimming","to swim"],0,"Después de can, el verbo no cambia."],["Fish can't ___.",["walk","walks","walking","to walk"],0,"Después de can't, el verbo no cambia."],["___ you dance? Yes, I can.",["Can","Is","Do","Are"],0,"La respuesta usa can."],["Can he play soccer? No, he ___.",["can't","isn't","don't","doesn't"],0,"Respondemos con can't."],["Birds ___ fly.",["can","cans","is","do"],0,"Can nunca lleva -s."],["I can ___ my name.",["write","writes","writing","wrote"],0,"Después de can, el verbo no cambia."]]},{"id":"k-a1-7","t":"There is, there are","s":"Hay","exp":["<b>There is</b> = hay (uno).","<b>There are</b> = hay (varios)."],"ex":[["There is a cat on the bed.","Hay un gato en la cama."],["There are two books on the desk.","Hay dos libros en el escritorio."],["There is a park near my house.","Hay un parque cerca de mi casa."],["There are five kids in my class.","Hay cinco niños en mi clase."]],"b":["There is a ball in the box.","There are three cats.","There is a bird in the tree.","There are many stars."],"q":[["There ___ a dog in the garden.",["is","are","am","be"],0,"Un perro: there is."],["There ___ four chairs.",["are","is","am","be"],0,"Varias sillas: there are."],["There ___ an apple on the table.",["is","are","am","be"],0,"Una manzana: there is."],["There ___ two pencils in my bag.",["are","is","am","be"],0,"Dos lápices: there are."],["___ a cake in the kitchen.",["There is","There are","It are","They is"],0,"Un pastel: there is."],["___ six eggs in the box.",["There are","There is","It is","They is"],0,"Seis huevos: there are."]]},{"id":"k-a1-8","t":"In, on, under","s":"¿Dónde está?","exp":["<b>in</b> = dentro","<b>on</b> = sobre, encima","<b>under</b> = debajo"],"ex":[["The cat is in the box.","El gato está dentro de la caja."],["The book is on the table.","El libro está sobre la mesa."],["The ball is under the bed.","La pelota está debajo de la cama."],["My shoes are under the chair.","Mis zapatos están debajo de la silla."]],"b":["The pencil is in my bag.","The cup is on the table.","The dog is under the bed.","My hat is on my head."],"q":[["The fish is ___ the water. (dentro)",["in","on","under","at"],0,"Dentro: in."],["The lamp is ___ the desk. (encima)",["on","in","under","at"],0,"Encima: on."],["The shoes are ___ the bed. (debajo)",["under","in","on","at"],0,"Debajo: under."],["The toys are ___ the box. (dentro)",["in","on","under","at"],0,"Dentro: in."],["The picture is ___ the wall.",["on","in","under","at"],0,"Las cosas pegadas a la pared van on."],["The cat is sleeping ___ the table. (debajo)",["under","on","in","at"],0,"Debajo: under."]]}],"writing":[{"id":"w-k-a1-1","t":"Capital letters","s":"Mayúsculas","exp":["La primera palabra de una oración empieza con <b>mayúscula</b>.","<b>I</b> (yo) siempre va con mayúscula.","Los nombres de personas y lugares también: <b>Ana</b>, <b>Monterrey</b>."],"ex":[["My dog is big.","Empieza con mayúscula."],["Sofía and I are friends.","Sofía e I con mayúscula."],["We live in Monterrey.","Monterrey con mayúscula."]],"q":[["Which one is correct?",["My cat is black.","my cat is black.","My Cat is black.","my Cat is black."],0,"Solo la primera palabra con mayúscula."],["Which one is correct?",["Leo and I play soccer.","leo and I play soccer.","Leo and i play soccer.","leo and i play soccer."],0,"Leo e I con mayúscula."],["Which one is correct?",["I live in Mexico.","I live in mexico.","i live in Mexico.","i live in mexico."],0,"I y Mexico con mayúscula."],["Which word needs a capital letter?",["ana","apple","dog","house"],0,"Ana es un nombre."],["Which one is correct?",["Today is Monday.","today is monday.","Today is monday.","today is Monday."],0,"Los días van con mayúscula en inglés."],["Which one is correct?",["Can I play?","can I play?","Can i play?","can i play?"],0,"Inicio de oración e I con mayúscula."]]},{"id":"w-k-a1-2","t":"Period and question mark","s":"Punto y signo de pregunta","exp":["Una oración termina con <b>punto</b>: I like cats<b>.</b>","Una pregunta termina con <b>?</b>: Do you like cats<b>?</b>","En inglés solo se pone el signo al final, no al principio."],"ex":[["I have a bike.","Oración: punto."],["Do you have a bike?","Pregunta: signo al final."],["What is your name?","Pregunta: signo al final."]],"q":[["Which one is correct?",["Is it a cat?","¿Is it a cat?","Is it a cat.","is it a cat?"],0,"Pregunta: solo ? al final."],["Which one is correct?",["I am happy.","I am happy?","i am happy.","I am happy"],0,"Oración: punto al final."],["What goes at the end? \"How old are you__\"",["?",".",",","!"],0,"Es pregunta."],["What goes at the end? \"My name is Sam__\"",[".","?",",","¿"],0,"Es oración: punto."],["Which one is correct?",["Where is my bag?","Where is my bag.","¿Where is my bag?","where is my bag?"],0,"Pregunta con mayúscula y ?."],["Which one is correct?",["We like pizza.","We like pizza?","we like pizza.","We like pizza,"],0,"Oración: mayúscula y punto."]]},{"id":"w-k-a1-3","t":"Spelling: everyday words","s":"Cómo se escribe","exp":["Algunas palabras se escriben distinto a como suenan.","Léelas en voz alta y fíjate en las letras.","friend · school · house · yellow · color · family"],"ex":[["My best friend is Ana.","friend: i antes de e."],["I go to school.","school: sch."],["My house is yellow.","yellow: doble l."]],"q":[["Which word is spelled correctly?",["friend","frend","freind","frient"],0,"f-r-i-e-n-d"],["Which word is spelled correctly?",["school","skool","scool","shool"],0,"s-c-h-o-o-l"],["Which word is spelled correctly?",["yellow","yelow","yello","yeloww"],0,"y-e-l-l-o-w"],["Which word is spelled correctly?",["family","famili","fammily","familly"],0,"f-a-m-i-l-y"],["Which word is spelled correctly?",["house","hous","haus","howse"],0,"h-o-u-s-e"],["Which word is spelled correctly?",["purple","purpel","purpl","perple"],0,"p-u-r-p-l-e"]]}],"phonics":[{"id":"ph-k-a1-1","t":"Short a, long a","s":"cap · cape","exp":["La <b>a</b> corta suena como en <b>cat</b>.","Si la palabra termina en <b>e</b> (la e mágica), la a dice su nombre: <b>cake</b>.","La e mágica no suena: cap → cap<b>e</b>."],"ex":[["cat · cap · hat","a corta"],["cake · cape · name","a larga"],["tap → tape","con e mágica"]],"q":[["Listen. Which word do you hear?",["cape","cap","cup","cop"],0,"Cape: a larga por la e mágica.","cape"],["Listen. Which word do you hear?",["hat","hate","hot","hut"],0,"Hat: a corta.","hat"],["Listen. Which word do you hear?",["made","mad","mud","mode"],0,"Made: a larga.","made"],["Which word has a long a?",["lake","bat","map","sad"],0,"Lake termina en e mágica."],["Which word has a short a?",["van","game","late","name"],0,"Van no tiene e mágica."],["Listen. Which word do you hear?",["tape","tap","top","tip"],0,"Tape: a larga.","tape"]]},{"id":"ph-k-a1-2","t":"Short i, long i","s":"kit · kite","exp":["La <b>i</b> corta suena como en <b>sit</b>.","Con e mágica, la i dice su nombre: <b>kite</b>, <b>bike</b>.","bit → bit<b>e</b> · pin → pin<b>e</b>"],"ex":[["sit · pig · fish","i corta"],["kite · bike · five","i larga"],["kit → kite","con e mágica"]],"q":[["Listen. Which word do you hear?",["kite","kit","cat","cut"],0,"Kite: i larga.","kite"],["Listen. Which word do you hear?",["pig","pie","peg","pug"],0,"Pig: i corta.","pig"],["Listen. Which word do you hear?",["bite","bit","bat","but"],0,"Bite: i larga.","bite"],["Which word has a long i?",["nine","sit","big","win"],0,"Nine termina en e mágica."],["Which word has a short i?",["fish","ride","time","like"],0,"Fish no tiene e mágica."],["Listen. Which word do you hear?",["pin","pine","pan","pen"],0,"Pin: i corta.","pin"]]},{"id":"ph-k-a1-3","t":"sh and ch","s":"ship · chip","exp":["<b>sh</b> suena como cuando pides silencio: <b>sh</b>ip, fi<b>sh</b>.","<b>ch</b> suena como en español: <b>ch</b>ip, lun<b>ch</b>.","Escucha bien el principio y el final de la palabra."],"ex":[["ship · shoe · fish","sh"],["chip · chair · lunch","ch"],["shop · chop","sh / ch"]],"q":[["Listen. Which word do you hear?",["ship","chip","sip","hip"],0,"Empieza con sh.","ship"],["Listen. Which word do you hear?",["chin","shin","thin","tin"],0,"Empieza con ch.","chin"],["Listen. Which word do you hear?",["shop","chop","stop","top"],0,"Empieza con sh.","shop"],["Which word starts with sh?",["shoe","chair","cheese","cherry"],0,"Shoe empieza con sh."],["Which word ends with ch?",["lunch","fish","wish","dish"],0,"Lunch termina en ch."],["Listen. Which word do you hear?",["cheese","sheep","sneeze","peas"],0,"Empieza con ch.","cheese"]]},{"id":"ph-k-a1-4","t":"Sight words","s":"the, said, was, they","exp":["Las <b>sight words</b> se reconocen de vista porque no siempre se leen como se escriben.","Aparecen en casi todos los cuentos.","Esta semana: <b>the, said, was, they, you, are, have, come</b>."],"ex":[["The cat said hello.","the · said"],["They are my friends.","they · are"],["You have a red bike.","you · have"]],"q":[["Listen. Which word do you hear?",["said","sad","side","seed"],0,"Said se lee \"sed\".","said"],["Listen. Which word do you hear?",["they","the","there","then"],0,"They.","they"],["Listen. Which word do you hear?",["was","saw","wax","wash"],0,"Was.","was"],["Listen. Which word do you hear?",["come","cone","comb","came"],0,"Come se lee \"cam\".","come"],["Choose the right word: \"___ you like pizza?\"",["Do","Have","Was","Said"],0,"Do you like…?"],["Listen. Which word do you hear?",["have","hive","half","hat"],0,"Have.","have"]]}],"vocab":[{"n":"At school","w":[["pencil","lápiz"],["eraser","goma"],["backpack","mochila"],["desk","pupitre"],["teacher","maestra"],["book","libro"],["crayons","crayolas"],["scissors","tijeras"],["glue","pegamento"],["ruler","regla"]]},{"n":"My house","w":[["kitchen","cocina"],["bedroom","recámara"],["bathroom","baño"],["living room","sala"],["door","puerta"],["window","ventana"],["bed","cama"],["table","mesa"],["chair","silla"],["garden","jardín"]]}]},"A1+":{"name":"Beginner plus","adv":0,"topics":[{"id":"k-a1p-1","t":"I am playing","s":"Present continuous"},{"id":"k-a1p-2","t":"What is he doing?","s":"Preguntas con -ing"},{"id":"k-a1p-3","t":"Do you like…?","s":"Yes, I do / No, I don't"},{"id":"k-a1p-4","t":"My day","s":"Present simple: rutinas"},{"id":"k-a1p-5","t":"My, your, his, her","s":"Posesivos"},{"id":"k-a1p-6","t":"A big dog","s":"Adjetivos antes del sustantivo"},{"id":"k-a1p-7","t":"How many…?","s":"Contar cosas"},{"id":"k-a1p-8","t":"Next to, behind, between","s":"Más preposiciones"}],"writing":[],"phonics":[],"vocab":[]},"A2":{"name":"Advanced","adv":1,"topics":[{"id":"k-a2-1","t":"Was / Were","s":"El pasado de to be"},{"id":"k-a2-2","t":"I played","s":"Past simple regular"},{"id":"k-a2-3","t":"I went","s":"Past simple irregular"},{"id":"k-a2-4","t":"Bigger, faster","s":"Comparativos"},{"id":"k-a2-5","t":"I am going to…","s":"Planes"},{"id":"k-a2-6","t":"Some / Any","s":"Cantidades"},{"id":"k-a2-7","t":"Must / Mustn't","s":"Reglas"},{"id":"k-a2-8","t":"Always, never","s":"Frecuencia"}],"writing":[],"phonics":[],"vocab":[]}},"children":{"A1":{"name":"Beginner","adv":0,"topics":[{"id":"c-a1-1","t":"Verb to be","s":"am, is, are","exp":["<b>I</b> → am · <b>he, she, it</b> → is · <b>you, we, they</b> → are","Contracciones: I'm, she's, we're, they're.","Negativo: <b>isn't</b>, <b>aren't</b>, I'm not."],"ex":[["I'm ten years old.","Tengo diez años."],["My dad is a doctor.","Mi papá es doctor."],["We aren't late.","No vamos tarde."],["Are they your cousins?","¿Son tus primos?"]],"b":["My brother is twelve years old.","We are in the same class.","She isn't my teacher.","Are you from Monterrey?"],"q":[["My best friend ___ very funny.",["is","am","are","be"],0,"Best friend = he/she: is."],["You and I ___ on the same team.",["are","is","am","be"],0,"You and I = we: are."],["I ___ not hungry right now.",["am","is","are","be"],0,"Con I: am."],["The windows ___ open.",["are","is","am","be"],0,"Windows es plural: are."],["___ your mom a teacher?",["Is","Are","Am","Does"],0,"Your mom = she: is."],["They ___ at home today. They're at the park.",["aren't","isn't","don't","not"],0,"They + negativo: aren't."]]},{"id":"c-a1-2","t":"Pronouns","s":"I, me · he, him · they, them","exp":["El pronombre <b>sujeto</b> va antes del verbo: <b>She</b> likes pizza.","El pronombre <b>objeto</b> va después del verbo o de una preposición: I like <b>her</b>.","I → me · he → him · she → her · we → us · they → them · you → you · it → it"],"ex":[["He calls me every day.","Él me llama todos los días."],["We visit them on Sundays.","Los visitamos los domingos."],["Can you help us?","¿Nos puedes ayudar?"],["I love it!","¡Me encanta!"]],"b":["She sits next to me.","I play soccer with them.","Can you call him later?","We like her new haircut."],"q":[["My sister is cool. I like ___ a lot.",["her","she","hers","his"],0,"Después del verbo: her."],["Tom and I are friends. ___ play video games together.",["We","Us","Our","They"],0,"Sujeto: we."],["Where are my keys? I can't find ___.",["them","they","their","it"],0,"Keys es plural; después del verbo: them."],["Mr. Garza is my teacher. ___ is very kind.",["He","Him","His","She"],0,"Sujeto: he."],["This gift is for ___. Thank you, Mom!",["me","I","my","mine"],0,"Después de for: me."],["Our grandparents live far away, so we call ___ every week.",["them","they","their","us"],0,"Objeto plural: them."]]},{"id":"c-a1-3","t":"Possessive adjectives","s":"my, your, his, her","exp":["Dicen de quién es algo y van <b>antes</b> del sustantivo.","I → <b>my</b> · you → <b>your</b> · he → <b>his</b> · she → <b>her</b>","it → <b>its</b> · we → <b>our</b> · they → <b>their</b>"],"ex":[["This is my backpack.","Esta es mi mochila."],["His name is Leo.","Su nombre es Leo (de él)."],["Her mom is a nurse.","Su mamá es enfermera (de ella)."],["The dog is eating its food.","El perro está comiendo su comida."]],"b":["My favorite color is green.","Her brother plays the drums.","Our house is near the school.","Their dog is very friendly."],"q":[["Leo has a bike. ___ bike is red.",["His","Her","Its","Their"],0,"Leo es niño: his."],["Ana and Sofía are sisters. ___ room is pink.",["Their","Her","Our","His"],0,"Dos personas: their."],["We love ___ new teacher.",["our","us","we","their"],0,"De nosotros: our."],["The cat is playing with ___ toy.",["its","it's","his","their"],0,"Para un animal o cosa: its."],["Is this ___ pencil, Mateo?",["your","you","yours","you're"],0,"De ti: your."],["My mom loves ___ job.",["her","his","she","their"],0,"Mom es mujer: her."]]},{"id":"c-a1-4","t":"Articles","s":"a, an, the","exp":["<b>a</b> antes de sonido de consonante: a book, a uniform.","<b>an</b> antes de sonido de vocal: an apple, an hour.","<b>the</b> cuando ya sabemos de cuál hablamos: the sun, the book on the table."],"ex":[["I have a dog and an iguana.","Tengo un perro y una iguana."],["The dog is brown.","El perro es café."],["She is an engineer.","Ella es ingeniera."],["Please close the door.","Por favor cierra la puerta."]],"b":["I eat an apple every day.","My uncle has a farm.","The moon is very bright tonight.","She wants to be an artist."],"q":[["My aunt is ___ engineer.",["an","a","the","—"],0,"Engineer empieza con sonido de vocal: an."],["I have ___ new phone.",["a","an","the","—"],0,"New empieza con sonido de consonante: a."],["Look at ___ sky! It's beautiful.",["the","a","an","—"],0,"Solo hay un cielo: the."],["We waited for ___ hour.",["an","a","the","—"],0,"Hour suena con vocal (la h es muda): an."],["He goes to ___ university in Monterrey.",["a","an","the","—"],0,"University suena \"yu\": a."],["I bought a shirt and a cap. ___ shirt is blue.",["The","A","An","—"],0,"Ya hablamos de esa camisa: the."]]},{"id":"c-a1-5","t":"Present simple","s":"I play, she plays","exp":["Para rutinas y cosas que siempre pasan.","Con <b>he, she, it</b> el verbo lleva <b>-s</b>: she plays.","-es en go, do, watch, wash: he <b>goes</b>, she <b>watches</b>.","Consonante + y → <b>-ies</b>: study → studies. Have → <b>has</b>."],"ex":[["I walk to school.","Camino a la escuela."],["My sister watches cartoons.","Mi hermana ve caricaturas."],["He goes to bed at nine.","Él se duerme a las nueve."],["We have English on Tuesdays.","Tenemos inglés los martes."]],"b":["My dad drives to work.","She studies every afternoon.","We eat lunch at two.","The bus leaves at seven."],"q":[["My brother ___ soccer every Saturday.",["plays","play","playing","is play"],0,"He + verbo con -s."],["She ___ to school by bus.",["goes","go","gos","going"],0,"Go → goes."],["My parents ___ in an office.",["work","works","working","is work"],0,"Parents = they: sin -s."],["Lucía ___ math every night.",["studies","studys","study","studyes"],0,"Consonante + y → -ies."],["The store ___ at nine in the morning.",["opens","open","opening","is open at"],0,"The store = it: opens."],["My cat ___ a long tail.",["has","have","haves","having"],0,"Have → has con it."]]},{"id":"c-a1-6","t":"Do / Does","s":"Preguntas y negativos","exp":["Pregunta: <b>Do</b> + I/you/we/they · <b>Does</b> + he/she/it.","Negativo: <b>don't</b> / <b>doesn't</b>.","Después de do, does, don't y doesn't el verbo <b>no lleva -s</b>: She doesn't <b>like</b>…"],"ex":[["Do you like pizza?","¿Te gusta la pizza?"],["Does your dad cook?","¿Tu papá cocina?"],["I don't eat meat.","No como carne."],["She doesn't play video games.","Ella no juega videojuegos."]],"b":["Do you have a pet?","Does she live near here?","My dog doesn't like baths.","We don't have school on Saturday."],"q":[["___ your sister speak French?",["Does","Do","Is","Are"],0,"Your sister = she: does."],["___ you walk to school?",["Do","Does","Are","Is"],0,"Con you: do."],["He doesn't ___ coffee.",["drink","drinks","drinking","drank"],0,"Después de doesn't, verbo sin -s."],["We ___ watch TV in the morning.",["don't","doesn't","aren't","not"],0,"Con we: don't."],["Does your teacher ___ a car?",["have","has","having","haves"],0,"Después de does, verbo base."],["My cat ___ like water.",["doesn't","don't","isn't","not"],0,"My cat = it: doesn't."]]},{"id":"c-a1-7","t":"There is / There are","s":"Hay","exp":["<b>There is</b> + una cosa · <b>There are</b> + varias.","Pregunta: <b>Is there…? Are there…?</b>","Negativo: <b>There isn't… / There aren't…</b>"],"ex":[["There is a pool in my building.","Hay una alberca en mi edificio."],["There are 25 students in my class.","Hay 25 alumnos en mi salón."],["Is there a bathroom here?","¿Hay un baño aquí?"],["There aren't any cookies left.","Ya no hay galletas."]],"b":["There is a big tree in my yard.","There are two bakeries on my street.","Is there a pharmacy near here?","There aren't any clouds today."],"q":[["There ___ a new student in our class.",["is","are","be","am"],0,"Un alumno: there is."],["There ___ many parks in Monterrey.",["are","is","be","am"],0,"Muchos parques: there are."],["___ there any milk in the fridge?",["Is","Are","Do","Does"],0,"Milk es incontable: is there."],["___ there any bananas?",["Are","Is","Do","Does"],0,"Bananas es plural: are there."],["There ___ any students in the classroom. It's empty.",["aren't","isn't","don't","not"],0,"Plural negativo: aren't."],["There ___ an old castle on the hill.",["is","are","has","have"],0,"Uno: there is (no usamos has)."]]},{"id":"c-a1-8","t":"Can","s":"Habilidad y permiso","exp":["<b>can</b> + verbo base para habilidad: I can swim.","También para pedir permiso: <b>Can I</b> go to the bathroom?","Negativo: <b>can't</b>. Can nunca lleva -s ni to."],"ex":[["My sister can speak three languages.","Mi hermana habla tres idiomas."],["I can't whistle.","No sé chiflar."],["Can I borrow your eraser?","¿Me prestas tu goma?"],["Can you help me, please?","¿Me puedes ayudar?"]],"b":["My grandpa can play the guitar.","Can I open the window?","I can't find my shoes.","Can you ride a horse?"],"q":[["My little brother can ___ to ten.",["count","counts","counting","to count"],0,"Después de can, verbo base."],["___ I go to the bathroom, please?",["Can","Do","Am","Does"],0,"Pedir permiso: can I…?"],["She ___ play the piano very well.",["can","cans","can to","is can"],0,"Can nunca lleva -s ni to."],["I'm sorry, I ___ come to your party.",["can't","don't can","not can","am not can"],0,"Negativo: can't."],["Can your dog ___ tricks?",["do","does","doing","did"],0,"Después de can, verbo base."],["Can you swim? — Yes, I ___.",["can","do","am","swim"],0,"Respuesta corta: Yes, I can."]]}],"writing":[],"phonics":[],"vocab":[{"n":"Daily routine","w":[["wake up","despertarse"],["get dressed","vestirse"],["brush my teeth","lavarme los dientes"],["have breakfast","desayunar"],["go to school","ir a la escuela"],["do homework","hacer la tarea"],["take a shower","bañarse"],["have dinner","cenar"],["go to bed","acostarse"],["walk the dog","pasear al perro"]]},{"n":"Food","w":[["bread","pan"],["cheese","queso"],["chicken","pollo"],["rice","arroz"],["beans","frijoles"],["eggs","huevos"],["milk","leche"],["juice","jugo"],["vegetables","verduras"],["fruit","fruta"]]}]},"A1+":{"name":"Beginner plus","adv":0,"topics":[{"id":"c-a1p-1","t":"Present continuous","s":"I am reading","exp":["Para lo que está pasando <b>ahora</b>.","<b>am / is / are</b> + verbo con <b>-ing</b>.","make → mak<b>ing</b> · swim → swim<b>ming</b> · lie → l<b>ying</b>"],"ex":[["I'm doing my homework.","Estoy haciendo mi tarea."],["She's talking on the phone.","Ella está hablando por teléfono."],["They're swimming in the pool.","Están nadando en la alberca."],["Is it raining?","¿Está lloviendo?"]],"b":["My mom is making dinner.","We are watching a movie.","The baby is sleeping now.","Are you listening to me?"],"q":[["Be quiet! The baby ___.",["is sleeping","sleeps","are sleeping","sleeping"],0,"Ahora mismo: is sleeping."],["Look! The kids ___ in the rain.",["are dancing","is dancing","dance","dancing"],0,"Kids = they: are + -ing."],["I ___ a letter to my grandma.",["am writing","am writeing","write","writing"],0,"Write → writing (sin e)."],["They are ___ in the lake.",["swimming","swiming","swim","swims"],0,"Swim → swimming (doble m)."],["What ___ you doing right now?",["are","is","do","does"],0,"Con you: are."],["He ___ playing. He's reading.",["isn't","aren't","doesn't","not"],0,"He + negativo: isn't."]]},{"id":"c-a1p-2","t":"Simple vs. continuous","s":"every day / right now","exp":["<b>Present simple</b> para rutinas: every day, usually, on Mondays.","<b>Present continuous</b> para ahora: now, right now, look!","Verbos como like, love, know, want casi siempre van en simple."],"ex":[["I usually walk to school, but today I'm taking the bus.","Normalmente camino, pero hoy voy en camión."],["She plays tennis on Fridays.","Ella juega tenis los viernes."],["Look! It's snowing!","¡Mira! ¡Está nevando!"],["I know the answer.","Sé la respuesta."]],"b":["My dad works in an office.","Right now he is working at home.","We usually eat at two.","I want a new backpack."],"q":[["My sister ___ the piano every day.",["practices","is practicing","practice","practicing"],0,"Every day: present simple."],["Shh! I ___ a movie.",["'m watching","watch","watches","'s watching"],0,"Ahora mismo: continuous."],["I ___ chocolate ice cream.",["love","am loving","loves","loving"],0,"Love casi siempre va en simple."],["Look! Your dog ___ the cake!",["is eating","eats","eat","are eating"],0,"Look! = ahora: continuous."],["We ___ to the beach every summer.",["go","are going","goes","going"],0,"Every summer: simple."],["Do you ___ the answer?",["know","knowing","knows","are knowing"],0,"Know va en simple."]]},{"id":"c-a1p-3","t":"Countable and uncountable","s":"apples / milk","exp":["<b>Contables</b>: se pueden contar (an apple, two apples).","<b>Incontables</b>: no se cuentan y no llevan -s (milk, water, rice, bread, money).","<b>some</b> en oraciones positivas · <b>any</b> en preguntas y negativos."],"ex":[["I need some eggs.","Necesito unos huevos."],["Is there any milk?","¿Hay leche?"],["We don't have any bread.","No tenemos pan."],["She drinks a lot of water.","Ella toma mucha agua."]],"b":["I want some orange juice.","There isn't any rice left.","Do you have any brothers?","We need some apples for the cake."],"q":[["Can I have ___ water, please?",["some","a","an","many"],0,"Water es incontable: some."],["There aren't ___ cookies in the jar.",["any","some","a","an"],0,"Negativo: any."],["Which word is uncountable?",["bread","sandwich","banana","egg"],0,"Bread no se cuenta."],["I'd like ___ banana.",["a","an","some","any"],0,"Una banana: a."],["Do we have ___ cheese?",["any","a","an","many"],0,"Pregunta con incontable: any."],["My mom bought ___ vegetables at the market.",["some","any","a","an"],0,"Positivo y plural: some."]]},{"id":"c-a1p-4","t":"How much / How many","s":"¿Cuánto? ¿Cuántos?","exp":["<b>How many</b> + contables en plural: How many books?","<b>How much</b> + incontables: How much water?","También: How much is it? = ¿Cuánto cuesta?"],"ex":[["How many brothers do you have?","¿Cuántos hermanos tienes?"],["How much sugar do you want?","¿Cuánta azúcar quieres?"],["How much is this T-shirt?","¿Cuánto cuesta esta playera?"],["How many people are coming?","¿Cuántas personas vienen?"]],"b":["How many pets do you have?","How much money do you need?","How many students are in your class?","How much is the movie ticket?"],"q":[["How ___ apples do we need?",["many","much","lot","more"],0,"Apples se cuenta: many."],["How ___ milk is in the fridge?",["much","many","lot","few"],0,"Milk no se cuenta: much."],["How ___ is this backpack? — It's 500 pesos.",["much","many","cost","price"],0,"Precio: how much."],["How many ___ are in the box?",["pencils","pencil","rice","water"],0,"How many + plural."],["How much ___ do you drink every day?",["water","bottles","glasses","cups"],0,"How much + incontable."],["How ___ hours do you sleep?",["many","much","long","lot"],0,"Hours se cuenta: many."]]},{"id":"c-a1p-5","t":"Possessive 's","s":"Ana's book","exp":["Para decir de quién es algo: <b>Ana's</b> book = el libro de Ana.","Plural con s: solo apóstrofo: my <b>parents'</b> car.","Plural sin s: <b>children's</b> toys.","Para preguntar: <b>Whose</b> bag is this?"],"ex":[["This is Leo's jacket.","Esta es la chamarra de Leo."],["My sister's room is pink.","El cuarto de mi hermana es rosa."],["The students' backpacks are in the hall.","Las mochilas de los alumnos están en el pasillo."],["Whose phone is this?","¿De quién es este celular?"]],"b":["This is my brother's guitar.","My parents' car is white.","Whose shoes are these?","The children's toys are everywhere."],"q":[["This is ___ notebook.",["Sofía's","Sofías","Sofía","Sofías'"],0,"El cuaderno de Sofía: Sofía's."],["My ___ house is very big. (Tengo dos abuelos.)",["grandparents'","grandparent's","grandparents's","grandparents"],0,"Plural con s: solo apóstrofo."],["___ pencil is this? — It's Mateo's.",["Whose","Who's","Who","Whom"],0,"Para preguntar de quién: whose."],["The ___ playground is new.",["children's","childrens'","childs'","children"],0,"Children es plural sin s: children's."],["I like ___ new haircut.",["my mom's","my moms","the mom of me","my mom"],0,"El corte de mi mamá: my mom's."],["Is that your ___ bike? (Tienes un hermano.)",["brother's","brothers'","brothers","brother"],0,"Un hermano: brother's."]]},{"id":"c-a1p-6","t":"In, on, at","s":"Preposiciones de tiempo","exp":["<b>at</b> + hora: at 7:00, at noon, at night.","<b>on</b> + día o fecha: on Monday, on May 5th, on my birthday.","<b>in</b> + mes, año, estación o parte del día: in July, in 2026, in summer, in the morning."],"ex":[["School starts at eight.","La escuela empieza a las ocho."],["We have art on Wednesdays.","Tenemos arte los miércoles."],["My birthday is in October.","Mi cumpleaños es en octubre."],["I read in the evening.","Leo en la tarde-noche."]],"b":["The party is on Saturday.","I wake up at six thirty.","We go to the beach in summer.","My cousin was born in 2015."],"q":[["The movie starts ___ 5:30.",["at","on","in","to"],0,"Hora: at."],["My birthday is ___ March.",["in","on","at","to"],0,"Mes: in."],["We have soccer practice ___ Tuesdays.",["on","in","at","to"],0,"Día: on."],["I do my homework ___ the afternoon.",["in","on","at","to"],0,"Parte del día: in the afternoon."],["Owls hunt ___ night.",["at","in","on","to"],0,"Expresión fija: at night."],["Mexico's Independence Day is ___ September 16th.",["on","in","at","to"],0,"Fecha: on."]]},{"id":"c-a1p-7","t":"Imperatives","s":"Open, Don't run, Let's go","exp":["Para dar instrucciones: verbo al inicio: <b>Open</b> your book.","Negativo: <b>Don't</b> + verbo: Don't run.","Para invitar: <b>Let's</b> + verbo: Let's play!"],"ex":[["Sit down, please.","Siéntate, por favor."],["Don't touch the oven.","No toques el horno."],["Let's go to the park.","Vamos al parque."],["Turn left at the bank.","Da vuelta a la izquierda en el banco."]],"b":["Please close the door.","Don't forget your lunch.","Let's watch a movie tonight.","Wash your hands before dinner."],"q":[["___ your book to page 20.",["Open","Opens","Opening","To open"],0,"Instrucción: verbo base al inicio."],["___ run in the hallway!",["Don't","Doesn't","Not","No"],0,"Prohibición: don't."],["It's hot. ___ go swimming!",["Let's","Lets","Let","Let us to"],0,"Invitación: let's."],["Please ___ quiet in the library.",["be","are","is","being"],0,"Instrucción con be: be quiet."],["___ forget your jacket. It's cold.",["Don't","Not","No","Doesn't"],0,"Don't + verbo."],["Let's ___ pizza tonight.",["order","ordering","to order","orders"],0,"Let's + verbo base."]]},{"id":"c-a1p-8","t":"Adverbs of frequency","s":"always, usually, never","exp":["always (100%) · usually · often · sometimes · rarely · never (0%)","Van <b>antes</b> del verbo: I <b>always</b> eat breakfast.","Pero <b>después</b> de to be: She is <b>never</b> late."],"ex":[["I always brush my teeth.","Siempre me lavo los dientes."],["We sometimes eat out.","A veces comemos fuera."],["He is usually happy.","Normalmente está contento."],["They never watch TV in the morning.","Nunca ven tele en la mañana."]],"b":["I usually walk to school.","My dad is always busy.","We never eat fast food.","She often reads before bed."],"q":[["Where does the adverb go?",["I always do my homework.","I do always my homework.","Always I do my homework.","I do my homework always do."],0,"Antes del verbo principal."],["Where does the adverb go?",["She is never late.","She never is late.","Never she is late.","She is late never."],0,"Después de to be."],["I ___ eat vegetables. I love them!",["always","never","rarely","don't"],0,"Si te encantan: always."],["He ___ goes to the gym. Maybe once a year.",["rarely","always","usually","often"],0,"Casi nunca: rarely."],["We ___ go to the beach in summer.",["usually","usual","usuallys","use"],0,"Adverbio: usually."],["My cat is ___ hungry!",["always","sometime","alway","ever"],0,"Always (siempre) va después de is."]]}],"writing":[],"phonics":[],"vocab":[{"n":"Clothes","w":[["shirt","camisa"],["pants","pantalones"],["skirt","falda"],["dress","vestido"],["jacket","chamarra"],["sweater","suéter"],["shoes","zapatos"],["sneakers","tenis"],["socks","calcetines"],["cap","gorra"]]},{"n":"Places in town","w":[["bakery","panadería"],["pharmacy","farmacia"],["library","biblioteca"],["bank","banco"],["post office","oficina de correos"],["supermarket","supermercado"],["gas station","gasolinera"],["movie theater","cine"],["park","parque"],["bus stop","parada del camión"]]}]},"A2":{"name":"Elementary","adv":0,"topics":[{"id":"c-a2-1","t":"Was / Were","s":"El pasado de to be","exp":["<b>I, he, she, it</b> → was","<b>you, we, they</b> → were","Negativo: <b>wasn't, weren't</b>. Pregunta: <b>Was she…? Were you…?</b>"],"ex":[["I was at home yesterday.","Ayer estaba en casa."],["They were at the beach.","Ellos estaban en la playa."],["The movie wasn't long.","La película no fue larga."],["Were you tired?","¿Estabas cansado?"]],"b":["I was sick last week.","We were at the museum.","The test wasn't difficult.","Was your brother at school?"],"q":[["My grandparents ___ in Saltillo last weekend.",["were","was","are","be"],0,"Grandparents = they: were."],["I ___ very tired yesterday.",["was","were","am","did"],0,"Con I en pasado: was."],["___ you at the party on Saturday?",["Were","Was","Did","Are"],0,"Con you: were."],["Sorry, the store ___ open yesterday. It was closed.",["wasn't","weren't","didn't","isn't"],0,"The store = it: wasn't."],["Where ___ you last night?",["were","was","did","are"],0,"Con you: were."],["It ___ cold this morning.",["was","were","is","did"],0,"Con it en pasado: was."]]},{"id":"c-a2-2","t":"Past simple: regular verbs","s":"I played, she studied","exp":["Agregamos <b>-ed</b>: play → played.","Si termina en e, solo <b>-d</b>: dance → danced.","Consonante + y → <b>-ied</b>: study → studied.","Palabras cortas con vocal + consonante duplican: stop → <b>stopped</b>."],"ex":[["We played soccer yesterday.","Ayer jugamos futbol."],["She danced at the party.","Ella bailó en la fiesta."],["I studied for the test.","Estudié para el examen."],["The bus stopped near my house.","El camión se detuvo cerca de mi casa."]],"b":["I watched a movie last night.","She cleaned her room yesterday.","We visited our cousins.","They studied for the test."],"q":[["Yesterday I ___ my grandma.",["visited","visit","visiting","visits"],0,"Yesterday pide pasado: visited."],["The past of study is…",["studied","studyed","studed","studing"],0,"Consonante + y → -ied."],["The past of stop is…",["stopped","stoped","stopt","stopping"],0,"Se duplica la p."],["She ___ the piano last night.",["played","plays","playing","play"],0,"Last night pide pasado."],["They ___ to music after school yesterday.",["listened","listen","listens","listening"],0,"Yesterday pide pasado."],["The past of try is…",["tried","tryed","trid","trying"],0,"Consonante + y → -ied."]]},{"id":"c-a2-3","t":"Past simple: irregular verbs","s":"went, ate, saw","exp":["Muchos verbos no usan -ed: se aprenden de memoria.","go → <b>went</b>, eat → <b>ate</b>, see → <b>saw</b>, have → <b>had</b>","buy → <b>bought</b>, make → <b>made</b>, take → <b>took</b>, come → <b>came</b>"],"ex":[["We went to the zoo.","Fuimos al zoológico."],["I ate pizza for lunch.","Comí pizza."],["She saw a rainbow.","Ella vio un arcoíris."],["My dad bought a new car.","Mi papá compró un carro nuevo."]],"b":["We went to the beach last summer.","I saw a movie with my friends.","She made a chocolate cake.","They ate tacos for dinner."],"q":[["The past of buy is…",["bought","buyed","brought","buied"],0,"Buy → bought (brought es de bring)."],["Last night we ___ hamburgers.",["ate","eated","eat","eaten"],0,"Eat → ate."],["She ___ to the park yesterday.",["went","goed","gone","go"],0,"Go → went."],["I ___ my keys at school this morning.",["left","leaved","leave","lefted"],0,"Leave → left."],["He ___ a picture of the mountains.",["took","taked","take","taken"],0,"Take → took."],["They ___ home late last night.",["came","comed","come","coming"],0,"Come → came."]]},{"id":"c-a2-4","t":"Did you…? I didn't…","s":"Preguntas y negativos en pasado","exp":["Negativo: <b>didn't</b> + verbo base: She didn't <b>go</b>.","Pregunta: <b>Did</b> + sujeto + verbo base: Did you <b>see</b> it?","Con did, el verbo regresa a su forma normal."],"ex":[["I didn't finish my homework.","No terminé mi tarea."],["Did you like the movie?","¿Te gustó la película?"],["She didn't eat breakfast.","Ella no desayunó."],["Where did they go?","¿A dónde fueron?"]],"b":["I didn't see you at school.","Did you finish your project?","We didn't go to the party.","What did you eat for lunch?"],"q":[["She didn't ___ the bus.",["take","took","takes","taking"],0,"Después de didn't, verbo base."],["___ you call your grandma yesterday?",["Did","Do","Were","Was"],0,"Pregunta en pasado: did."],["Did they ___ the game?",["win","won","wins","winning"],0,"Después de did, verbo base."],["Where ___ you go last weekend?",["did","were","do","was"],0,"Pregunta en pasado: did."],["I ___ like the soup yesterday. It was too salty.",["didn't","wasn't","don't","not"],0,"Negativo en pasado: didn't."],["What time did you ___ up today?",["wake","woke","waked","waking"],0,"Después de did, verbo base."]]},{"id":"c-a2-5","t":"Comparatives","s":"bigger, more interesting","exp":["Palabras cortas: <b>-er + than</b>: tall → taller than.","Termina en y: <b>-ier</b>: easy → easier.","Palabras largas: <b>more</b> + adjetivo: more interesting.","Irregulares: good → <b>better</b>, bad → <b>worse</b>."],"ex":[["My brother is taller than me.","Mi hermano es más alto que yo."],["Cats are smaller than dogs.","Los gatos son más chicos que los perros."],["This book is more interesting than that one.","Este libro es más interesante que ese."],["Today is better than yesterday.","Hoy es mejor que ayer."]],"b":["A car is faster than a bike.","My sister is older than me.","Math is easier than science.","This movie is more exciting than the book."],"q":[["An elephant is ___ than a horse.",["bigger","biger","more big","biggest"],0,"Big → bigger (se duplica la g)."],["Summer is ___ than winter.",["hotter","hoter","more hot","hottest"],0,"Hot → hotter."],["This test is ___ than the last one.",["easier","easyer","more easy","easiest"],0,"Easy → easier."],["Soccer is ___ than chess for me.",["more exciting","excitinger","most exciting","exciting more"],0,"Palabra larga: more exciting."],["My grades are ___ than last month.",["better","gooder","more good","best"],0,"Good → better."],["The weather is ___ than yesterday. It's raining a lot.",["worse","badder","more bad","worst"],0,"Bad → worse."]]},{"id":"c-a2-6","t":"Superlatives","s":"the biggest, the best","exp":["<b>the + -est</b>: tall → the tallest.","Termina en y: <b>-iest</b>: happy → the happiest.","Palabras largas: <b>the most</b> + adjetivo.","Irregulares: good → <b>the best</b>, bad → <b>the worst</b>."],"ex":[["She is the youngest in her family.","Ella es la más chica de su familia."],["This is the most beautiful beach.","Esta es la playa más bonita."],["That was the best day ever.","Ese fue el mejor día de todos."],["He is the tallest boy in class.","Él es el niño más alto del salón."]],"b":["He is the tallest boy in my class.","This is the best pizza in town.","Winter is the coldest season.","That was the most difficult test."],"q":[["The cheetah is the ___ land animal.",["fastest","faster","most fast","fastiest"],0,"Fast → the fastest."],["This is the ___ book in the library.",["most interesting","interestingest","more interesting","most interestinger"],0,"Palabra larga: the most."],["My grandpa is the ___ person in my family.",["oldest","older","olderest","most old"],0,"Old → the oldest."],["It was the ___ day of my life!",["best","goodest","better","most good"],0,"Good → the best."],["She is the ___ student in our class.",["happiest","happyest","more happy","most happiest"],0,"Happy → the happiest."],["That was the ___ movie ever. I fell asleep.",["worst","baddest","worse","most bad"],0,"Bad → the worst."]]},{"id":"c-a2-7","t":"Going to","s":"Planes","exp":["Para planes: <b>am / is / are + going to</b> + verbo.","Negativo: I'm <b>not</b> going to… Pregunta: <b>Are you</b> going to…?","También para algo que vemos que va a pasar: Look at the clouds! It's going to rain."],"ex":[["I am going to visit my cousins.","Voy a visitar a mis primos."],["We are going to watch a movie tonight.","Vamos a ver una película."],["She isn't going to come.","Ella no va a venir."],["Are you going to play?","¿Vas a jugar?"]],"b":["I am going to study tonight.","We are going to travel to Cancún.","They are going to buy a new car.","Is she going to come to the party?"],"q":[["I ___ going to call my mom.",["am","is","are","be"],0,"Con I: am."],["They are going ___ soccer.",["to play","play","playing","played"],0,"Going to + verbo."],["She ___ going to wear her blue dress.",["is","am","are","be"],0,"Con she: is."],["___ you going to come?",["Are","Is","Do","Will"],0,"Con you: are."],["We aren't going ___ the bus.",["to take","take","taking","took"],0,"Going to + verbo."],["Look at those clouds! It ___ rain.",["is going to","are going to","going to","is going"],0,"Lo vemos venir: is going to."]]},{"id":"c-a2-8","t":"Will","s":"Predicciones y decisiones","exp":["<b>will</b> + verbo para predicciones: I think it will rain.","Para decidir en el momento: I'll help you.","Negativo: <b>won't</b>."],"ex":[["I think you will love this book.","Creo que te va a encantar este libro."],["It's cold. I'll close the window.","Hace frío. Cierro la ventana."],["Robots will help us in the future.","Los robots nos ayudarán en el futuro."],["Don't worry, I won't tell anyone.","No te preocupes, no le diré a nadie."]],"b":["I think it will be sunny tomorrow.","I'll help you with your homework.","She won't be late.","Will you come to my party?"],"q":[["The phone is ringing. I ___ answer it.",["'ll","will to","'m","am"],0,"Decisión del momento: I'll."],["I think people ___ live on Mars one day.",["will","are","will to","is"],0,"Predicción: will."],["In the future, cars ___ fly.",["will","are","will to","does"],0,"Predicción: will."],["Don't worry, I ___ forget.",["won't","willn't","don't will","not will"],0,"Will not = won't."],["___ you help me, please?",["Will","Are","Do","Is"],0,"Petición: will you…?"],["I promise I ___ call you tonight.",["will","am","will to","going"],0,"Promesa: will."]]},{"id":"c-a2-9","t":"Should / Shouldn't","s":"Consejos","exp":["Para dar consejos: <b>should</b> + verbo.","Para decir que algo no es buena idea: <b>shouldn't</b>.","Después de should el verbo no cambia."],"ex":[["You should drink more water.","Deberías tomar más agua."],["You shouldn't eat too much candy.","No deberías comer muchos dulces."],["We should wear a helmet.","Deberíamos usar casco."],["Should I bring a jacket?","¿Debería llevar chamarra?"]],"b":["You should go to bed early.","You shouldn't run in the hallway.","We should help our parents.","Should I call the doctor?"],"q":[["You have a fever. You ___ go to the doctor.",["should","shouldn't","should to","shoulds"],0,"Es buen consejo: should."],["You ___ play video games all night.",["shouldn't","should","should to","shoulds"],0,"No es buena idea: shouldn't."],["She should ___ for the test.",["study","studies","to study","studying"],0,"Después de should, verbo base."],["It's raining. You ___ take an umbrella.",["should","shouldn't","should to","shoulds"],0,"Buen consejo: should."],["You ___ talk during the test.",["shouldn't","should","should to","shoulds"],0,"No es buena idea: shouldn't."],["I'm hungry. — You ___ eat something.",["should","shouldn't","should to","shoulds"],0,"Buen consejo: should."]]},{"id":"c-a2-10","t":"Must / Have to","s":"Reglas y obligaciones","exp":["<b>must</b> = regla u obligación fuerte.","<b>have to / has to</b> = es necesario.","<b>mustn't</b> = está prohibido.","<b>don't have to</b> = no es necesario."],"ex":[["You must wear a seatbelt.","Debes usar cinturón."],["I have to clean my room.","Tengo que limpiar mi cuarto."],["You don't have to bring lunch.","No necesitas traer lonche."],["You mustn't use your phone in class.","No debes usar el celular en clase."]],"b":["I have to finish my homework.","You must wear a helmet.","She doesn't have to work today.","We mustn't be late."],"q":[["My brother ___ to walk the dog every day.",["has","have","must","is"],0,"Con he: has to."],["Don't touch that. You ___ touch it. It's hot!",["mustn't","don't have to","must","have to"],0,"Está prohibido: mustn't."],["It's Saturday. I ___ go to school.",["don't have to","mustn't","must","have to"],0,"No es necesario: don't have to."],["Students ___ wear a uniform.",["must","musts","must to","musting"],0,"Must nunca lleva -s ni to."],["Do you ___ wear a uniform at your school?",["have to","must","has to","having to"],0,"Pregunta con do: have to."],["We ___ to buy milk. There isn't any.",["have","has","must","are"],0,"Con we: have to."]]}],"writing":[{"id":"w-c-a2-1","t":"Capital letters","s":"Días, meses, países, idiomas","exp":["En inglés van con mayúscula: días (<b>Monday</b>), meses (<b>July</b>), países (<b>Canada</b>), idiomas y nacionalidades (<b>Spanish</b>, <b>Mexican</b>).","Las estaciones van en minúscula: summer, winter.","Títulos de libros y películas: palabras principales con mayúscula."],"ex":[["My birthday is on Friday, March 6th.","Día y mes con mayúscula."],["She speaks English and French.","Idiomas con mayúscula."],["We went to Spain last summer.","País con mayúscula, estación no."]],"q":[["Which one is correct?",["I was born in April.","I was born in april.","i was born in April.","I was Born in April."],0,"Meses con mayúscula."],["Which one is correct?",["My cousin is Mexican.","My cousin is mexican.","my cousin is Mexican.","My Cousin is Mexican."],0,"Nacionalidades con mayúscula."],["Which one is correct?",["We study French on Thursdays.","We study french on thursdays.","We study French on thursdays.","We study french on Thursdays."],0,"Idiomas y días con mayúscula."],["Which one is correct?",["I love winter in Canada.","I love Winter in Canada.","I love winter in canada.","I love Winter in canada."],0,"Estaciones en minúscula; países con mayúscula."],["Which one is correct?",["My favorite book is Harry Potter.","My favorite book is harry potter.","my favorite book is Harry Potter.","My Favorite Book is Harry potter."],0,"Nombres de títulos con mayúscula."],["Which word needs a capital letter?",["japanese","summer","morning","school"],0,"Japanese es idioma o nacionalidad."]]},{"id":"w-c-a2-2","t":"Commas in lists","s":"red, blue, and green","exp":["Usamos <b>comas</b> para separar tres o más cosas en una lista.","Antes de la última va <b>and</b> (o <b>or</b>), y en inglés americano también lleva coma: red, white, and blue.","Con solo dos cosas no se usa coma: cats and dogs."],"ex":[["I like apples, bananas, and grapes.","Tres cosas: comas."],["We need eggs, milk, and bread.","Coma antes de and."],["Do you want tea or coffee?","Dos cosas: sin coma."]],"q":[["Which one is correct?",["I play soccer, tennis, and basketball.","I play soccer tennis and basketball.","I play, soccer, tennis, and basketball.","I play soccer, tennis and, basketball."],0,"Comas entre las tres cosas."],["Which one is correct?",["My dog is big and friendly.","My dog is big, and friendly.","My dog, is big and friendly.","My dog is, big and friendly."],0,"Solo dos cosas: sin coma."],["Which one is correct?",["We visited Mexico City, Puebla, and Oaxaca.","We visited Mexico City Puebla and Oaxaca.","We visited, Mexico City, Puebla, and Oaxaca.","We visited Mexico City, Puebla and, Oaxaca."],0,"Comas en la lista."],["Which one is correct?",["She bought a pen, a ruler, and a notebook.","She bought a pen a ruler and a notebook.","She bought, a pen, a ruler, and a notebook.","She bought a pen, a ruler, and, a notebook."],0,"Comas en la lista."],["Where does the comma go? \"I need paper__ glue__ and scissors.\"",["paper, glue, and","paper glue, and","paper, glue and,","paper glue and"],0,"Después de cada cosa menos la última."],["Which one is correct?",["Do you want juice or water?","Do you want juice, or water?","Do you want, juice or water?","Do you, want juice or water?"],0,"Dos cosas: sin coma."]]},{"id":"w-c-a2-3","t":"Spelling: -ed and -ing","s":"stopped, studying, writing","exp":["Termina en e: quita la e con -ing (write → <b>writing</b>) y agrega solo -d (like → <b>liked</b>).","Vocal + consonante corta: dobla la consonante (stop → <b>stopped</b>, run → <b>running</b>).","Consonante + y: -ied en pasado (study → <b>studied</b>), pero -ing se queda igual (<b>studying</b>)."],"ex":[["She is writing a story.","write → writing"],["The car stopped.","stop → stopped"],["I studied all night.","study → studied"]],"q":[["Which word is spelled correctly?",["running","runing","runnig","runnning"],0,"Doble n."],["Which word is spelled correctly?",["making","makeing","makking","makin"],0,"Quita la e."],["Which word is spelled correctly?",["planned","planed","plannd","plannned"],0,"Doble n."],["Which word is spelled correctly?",["cried","cryed","cride","cryied"],0,"Consonante + y → -ied."],["Which word is spelled correctly?",["studying","studing","studiing","studyng"],0,"Con -ing la y se queda."],["Which word is spelled correctly?",["danced","danceed","dancd","dancced"],0,"Termina en e: solo -d."]]}],"phonics":[],"vocab":[{"n":"Travel","w":[["suitcase","maleta"],["passport","pasaporte"],["ticket","boleto"],["airport","aeropuerto"],["flight","vuelo"],["map","mapa"],["luggage","equipaje"],["tourist","turista"],["souvenir","recuerdo"],["trip","viaje"]]},{"n":"Jobs","w":[["nurse","enfermero"],["firefighter","bombero"],["mechanic","mecánico"],["cook","cocinero"],["lawyer","abogado"],["engineer","ingeniero"],["farmer","granjero"],["pilot","piloto"],["dentist","dentista"],["vet","veterinario"]]}]},"A2+":{"name":"Elementary plus","adv":0,"topics":[{"id":"c-a2p-1","t":"Past continuous","s":"I was walking"},{"id":"c-a2p-2","t":"Past simple vs. continuous","s":"when / while"},{"id":"c-a2p-3","t":"Present perfect: ever / never","s":"Have you ever…?"},{"id":"c-a2p-4","t":"Already, yet, just","s":"Present perfect"},{"id":"c-a2p-5","t":"First conditional","s":"If it rains, we will…"},{"id":"c-a2p-6","t":"Too / Enough","s":"too cold, big enough"},{"id":"c-a2p-7","t":"Who, which, that","s":"Relativos"},{"id":"c-a2p-8","t":"A lot of, a few, a little","s":"Cuantificadores"}],"writing":[],"phonics":[],"vocab":[]},"B1":{"name":"Intermediate","adv":0,"topics":[{"id":"c-b1-1","t":"Present perfect vs. past simple","s":"have seen / saw"},{"id":"c-b1-2","t":"For / Since","s":"for two years"},{"id":"c-b1-3","t":"Second conditional","s":"If I had…, I would…"},{"id":"c-b1-4","t":"Passive voice","s":"is made, was built"},{"id":"c-b1-5","t":"Reported speech","s":"She said that…"},{"id":"c-b1-6","t":"Gerunds and infinitives","s":"enjoy playing, want to play"},{"id":"c-b1-7","t":"Used to","s":"I used to…"},{"id":"c-b1-8","t":"Might / May","s":"Posibilidad"}],"writing":[],"phonics":[],"vocab":[]},"B1+":{"name":"Advanced","adv":1,"topics":[{"id":"c-b1p-1","t":"Past perfect","s":"had already left"},{"id":"c-b1p-2","t":"Third conditional","s":"If I had known…"},{"id":"c-b1p-3","t":"Reported questions","s":"She asked if…"},{"id":"c-b1p-4","t":"Relative clauses","s":"who, which, whose"},{"id":"c-b1p-5","t":"Wish","s":"I wish I could…"},{"id":"c-b1p-6","t":"Question tags","s":"It's cold, isn't it?"}],"writing":[],"phonics":[],"vocab":[]}},"teens":{"A1":{"name":"Beginner","adv":0,"topics":[{"id":"t-a1-1","t":"Verb to be","s":"am, is, are"},{"id":"t-a1-2","t":"Present simple","s":"Routines and habits"},{"id":"t-a1-3","t":"Adverbs of frequency","s":"always, usually, never"},{"id":"t-a1-4","t":"There is / There are","s":"Describing places"},{"id":"t-a1-5","t":"Can / Can't","s":"Ability"},{"id":"t-a1-6","t":"Possessives","s":"my, your, Ana's"},{"id":"t-a1-7","t":"Articles","s":"a, an, the"},{"id":"t-a1-8","t":"Imperatives","s":"Do / Don't"}],"writing":[],"phonics":[],"vocab":[]},"A1+":{"name":"Beginner plus","adv":0,"topics":[{"id":"t-a1p-1","t":"Present continuous","s":"Right now"},{"id":"t-a1p-2","t":"Simple vs. continuous","s":"Habits vs. now"},{"id":"t-a1p-3","t":"Past of be","s":"was, were"},{"id":"t-a1p-4","t":"Past simple","s":"Regular and irregular"},{"id":"t-a1p-5","t":"Countable and uncountable","s":"some, any, much, many"},{"id":"t-a1p-6","t":"In, on, at","s":"Time prepositions"},{"id":"t-a1p-7","t":"Object pronouns","s":"me, him, them"},{"id":"t-a1p-8","t":"Like + -ing","s":"I love gaming"}],"writing":[],"phonics":[],"vocab":[]},"A2":{"name":"Elementary","adv":0,"topics":[{"id":"t-a2-1","t":"Past simple questions","s":"Did you…?"},{"id":"t-a2-2","t":"Past continuous","s":"was / were + -ing"},{"id":"t-a2-3","t":"Comparatives and superlatives","s":"bigger, the best"},{"id":"t-a2-4","t":"Going to vs. will","s":"Plans and predictions"},{"id":"t-a2-5","t":"Present perfect","s":"Life experiences"},{"id":"t-a2-6","t":"Should, must, have to","s":"Advice and obligation"},{"id":"t-a2-7","t":"First conditional","s":"Real possibilities"},{"id":"t-a2-8","t":"Too / Enough","s":"Limits"},{"id":"t-a2-9","t":"Quantifiers","s":"a lot of, a few, a little"},{"id":"t-a2-10","t":"Adverbs of manner","s":"quickly, well"}],"writing":[],"phonics":[],"vocab":[]},"A2+":{"name":"Elementary plus","adv":0,"topics":[{"id":"t-a2p-1","t":"Already, yet, just","s":"Present perfect"},{"id":"t-a2p-2","t":"For / Since","s":"Duration"},{"id":"t-a2p-3","t":"Present perfect vs. past simple","s":"Finished or not"},{"id":"t-a2p-4","t":"Used to","s":"Past habits"},{"id":"t-a2p-5","t":"Relative clauses","s":"who, which, that, where"},{"id":"t-a2p-6","t":"Zero and first conditional","s":"Facts and results"},{"id":"t-a2p-7","t":"Might / May","s":"Possibility"},{"id":"t-a2p-8","t":"Verb + gerund / infinitive","s":"enjoy doing, decide to do"}],"writing":[],"phonics":[],"vocab":[]},"B1":{"name":"Intermediate","adv":0,"topics":[{"id":"t-b1-1","t":"Present perfect continuous","s":"I've been waiting","exp":["Form: <b>have / has been + -ing</b>.","Use it for actions that started in the past and are still happening.","Also for recent actions with visible results: I'm tired. I've been running.","Common with <b>for</b> and <b>since</b>, and with <b>How long…?</b>"],"ex":[["I've been studying for two hours.",""],["She's been working here since June.",""],["It's been raining all day.",""],["Why are you so tired? — I've been running.",""]],"b":["I have been waiting for the bus for twenty minutes.","She has been learning Korean since January.","They have been playing video games all afternoon.","How long have you been living here?"],"q":[["I ___ studying English since I was ten.",["have been","has been","am","was"],0,"I + have been + -ing."],["How long ___ you been waiting?",["have","has","did","are"],0,"Question form: have you been…?"],["Her hands are dirty because she ___ in the garden.",["has been working","have been working","has been work","is been working"],0,"She + has been + -ing."],["It ___ since this morning.",["has been raining","have been raining","is raining","was raining"],0,"Since + an unfinished action: has been + -ing."],["They have been friends ___ 2019.",["since","for","from","during"],0,"Since + a point in time."],["I've been reading this book ___ three days.",["for","since","from","during"],0,"For + a period of time."]]},{"id":"t-b1-2","t":"Second conditional","s":"If I had…, I would…","exp":["Use it for imaginary or unlikely situations now or in the future.","Form: <b>If + past simple, would + base verb</b>.","With be, <b>If I were…</b> is preferred."],"ex":[["If I had more money, I would travel.",""],["If she lived closer, we'd see her more often.",""],["What would you do if you won the lottery?",""],["If I were taller, I'd play basketball.",""]],"b":["If I had a car, I would drive to the beach.","What would you do if you lost your phone?","If we lived in Canada, we would see snow every winter.","She would be happier if she slept more."],"q":[["If I ___ a dog, I would walk it every day.",["had","have","would have","will have"],0,"If + past simple."],["If she studied more, she ___ better grades.",["would get","will get","gets","got"],0,"Result: would + base verb."],["What ___ you do if you saw a ghost?",["would","will","did","do"],0,"Imaginary situation: would."],["If I ___ the principal, I would cancel homework.",["were","am","will be","be"],0,"If I were…"],["We'd go swimming if it ___ so cold.",["weren't","isn't","wouldn't be","won't be"],0,"If + past simple: weren't."],["If they ___ to bed earlier, they wouldn't be so tired.",["went","go","would go","will go"],0,"If + past simple."]]},{"id":"t-b1-3","t":"Passive voice","s":"is made, was built","exp":["Form: <b>be + past participle</b>.","Use it when the action matters more than who did it.","Present: <b>is / are made</b>. Past: <b>was / were built</b>.","Add <b>by</b> + person only if it's important."],"ex":[["English is spoken all over the world.",""],["These phones are made in Korea.",""],["The bridge was built in 1920.",""],["The thieves were caught by the police.",""]],"b":["Coffee is grown in Veracruz.","The letter was written by my grandmother.","The windows are cleaned every week.","The museum was opened in 1995."],"q":[["Spanish ___ in many countries.",["is spoken","speaks","is speaking","spoken"],0,"Present passive: is + participle."],["The Mona Lisa ___ by Leonardo da Vinci.",["was painted","painted","is painting","was paint"],0,"Past passive: was + participle."],["These cookies ___ with real butter.",["are made","is made","make","are make"],0,"Plural present passive: are made."],["The game ___ because of the rain.",["was canceled","canceled","was cancel","has cancel"],0,"Past passive: was canceled."],["Our car ___ last night.",["was stolen","stole","was stole","stolen"],0,"Steal → stolen."],["Thousands of emails ___ every second.",["are sent","are send","sends","is sent"],0,"Plural present passive: are sent."]]},{"id":"t-b1-4","t":"Reported speech","s":"She said that…","exp":["Tenses usually move back: is → <b>was</b>, will → <b>would</b>, can → <b>could</b>, past → <b>had + participle</b>.","<b>tell</b> + person: He told me… / <b>say</b> + that: He said that…","Pronouns and time words change: today → that day, tomorrow → the next day."],"ex":[["\"I'm tired.\" → She said she was tired.",""],["\"I will call you.\" → He said he would call me.",""],["\"We can't come.\" → They said they couldn't come.",""],["\"I lost my keys.\" → He told me he had lost his keys.",""]],"b":["She said she was hungry.","He told me he would help.","They said they couldn't come to the party.","My mom said that dinner was ready."],"q":[["\"I like pizza.\" → She said she ___ pizza.",["liked","likes","like","had like"],0,"Present → past."],["\"I will be late.\" → He said he ___ late.",["would be","will be","was being","is"],0,"Will → would."],["\"I can swim.\" → She said she ___ swim.",["could","can","would","is able"],0,"Can → could."],["He ___ me he was busy.",["told","said","say","talked"],0,"Tell + person."],["She ___ that she was busy.",["said","told","tell","spoke"],0,"Say + that."],["\"I saw the movie.\" → He said he ___ the movie.",["had seen","has seen","saw seen","sees"],0,"Past → had + participle."]]},{"id":"t-b1-5","t":"Reported questions","s":"She asked if…","exp":["Use statement word order: She asked where <b>I lived</b> (not \"where did I live\").","Yes/no questions use <b>if</b> or <b>whether</b>.","Tenses move back, as in reported statements."],"ex":[["\"Where do you live?\" → She asked me where I lived.",""],["\"Are you OK?\" → He asked if I was OK.",""],["\"What time does it start?\" → They asked what time it started.",""],["\"Can you help me?\" → She asked whether I could help her.",""]],"b":["She asked me where I lived.","He asked if I was ready.","They asked what time the show started.","My teacher asked whether we had finished."],"q":[["\"Where are you going?\" → He asked me where ___.",["I was going","was I going","I am going","am I going"],0,"Statement order + backshift."],["\"Do you like jazz?\" → She asked ___ I liked jazz.",["if","that","what","do"],0,"Yes/no question: if."],["\"What's your name?\" → They asked what my name ___.",["was","is it","was it","did"],0,"Statement order: my name was."],["\"Can you drive?\" → He asked if I ___ drive.",["could","can","did","would can"],0,"Can → could."],["\"Why did you leave?\" → She asked why I ___.",["had left","did leave","left had","have leave"],0,"Past → had + participle."],["\"When does the store open?\" → I asked when the store ___.",["opened","does open","did open","open"],0,"Statement order + past."]]},{"id":"t-b1-6","t":"Past perfect","s":"had already left","exp":["Form: <b>had + past participle</b>.","Use it for an action that happened before another past action.","Common with <b>when, before, after, by the time, already, never</b>."],"ex":[["When I arrived, the movie had already started.",""],["She had never seen the ocean before that trip.",""],["They had eaten before we got there.",""],["I realized I had left my phone at home.",""]],"b":["When we arrived, the train had already left.","She had never flown before that summer.","I had finished my homework before dinner.","Had you met him before the party?"],"q":[["By the time I woke up, my parents ___ to work.",["had gone","have gone","went had","had go"],0,"Earlier past action: had gone."],["She was nervous because she ___ on stage before.",["hadn't performed","haven't performed","didn't performed","hadn't perform"],0,"Had + not + participle."],["When I got to the store, it ___.",["had closed","has closed","closes","had close"],0,"It closed before I got there."],["I ___ that book before, so I knew the ending.",["had read","have read","had readed","was read"],0,"Read → read (participle)."],["After she ___ her homework, she watched TV.",["had finished","has finished","had finish","finishing"],0,"First action: had finished."],["They ___ each other for years before they got married.",["had known","have known","had knew","were knowing"],0,"Know → known."]]},{"id":"t-b1-7","t":"Wish + past","s":"I wish I had…","exp":["Use <b>wish + past simple</b> for present situations you'd like to be different.","Use <b>wish + could</b> for abilities.","<b>I wish I were…</b> is preferred with be."],"ex":[["I wish I had more free time.",""],["She wishes she lived near the beach.",""],["I wish I could speak Japanese.",""],["I wish it weren't so hot.",""]],"b":["I wish I had a bigger room.","She wishes she could drive.","I wish my friends lived closer.","We wish it were the weekend."],"q":[["I wish I ___ taller.",["were","am","will be","would"],0,"Wish + were."],["He wishes he ___ more money.",["had","has","have","will have"],0,"Wish + past simple."],["I wish I ___ play the guitar.",["could","can","will","would can"],0,"Ability: could."],["They wish they ___ in a big city.",["lived","live","living","will live"],0,"Wish + past simple."],["I wish it ___ raining.",["weren't","isn't","won't","doesn't"],0,"Wish + past: weren't."],["She wishes she ___ so many tests this week.",["didn't have","doesn't have","don't have","hasn't"],0,"Wish + past simple."]]},{"id":"t-b1-8","t":"Must, might, can't","s":"Making deductions","exp":["<b>must</b> = you're almost sure it's true.","<b>can't</b> = you're almost sure it's not true.","<b>might / may / could</b> = it's possible."],"ex":[["She's not answering. She must be asleep.",""],["That can't be Tom. He's in Paris.",""],["It might rain later.",""],["The keys could be in the car.",""]],"b":["He must be very tired.","That can't be true.","She might be at the library.","They may come to the party."],"q":[["The lights are off. They ___ be at home.",["can't","must","should","have to"],0,"Almost sure it's not true: can't."],["She's smiling from ear to ear. She ___ be happy.",["must","can't","mustn't","has to"],0,"Almost sure it's true: must."],["I'm not sure where Ana is. She ___ be at the gym.",["might","must","can't","has to"],0,"Possible: might."],["That ___ be Leo's bike. His is red, and this one is blue.",["can't","must","might","should"],0,"Almost sure it's not true: can't."],["He has three cars and a boat. He ___ be rich.",["must","can't","mustn't","shouldn't"],0,"Almost sure it's true: must."],["Take an umbrella. It ___ rain this afternoon.",["might","must","can't","has to"],0,"Possible: might."]]},{"id":"t-b1-9","t":"Relative clauses","s":"who, which, that, where, whose","exp":["<b>who</b> for people, <b>which</b> for things, <b>that</b> for both.","<b>where</b> for places, <b>whose</b> for possession.","Extra information goes between commas, and there you can't use <b>that</b>."],"ex":[["The girl who sits next to me is from Chile.",""],["The phone that I bought is great.",""],["My grandmother, who is 80, still swims.",""],["This is the café where we met.",""]],"b":["The man who lives next door is a doctor.","This is the book that I told you about.","That is the school where my mom works.","She is the girl whose dog won the contest."],"q":[["The teacher ___ helped me is very kind.",["who","which","where","whose"],0,"People: who."],["The movie ___ we watched was boring.",["that","who","where","whose"],0,"Things: that or which."],["That's the park ___ we play soccer.",["where","which","who","whose"],0,"Places: where."],["She's the girl ___ brother is in my class.",["whose","who","who's","which"],0,"Possession: whose."],["My phone, ___ is very old, still works.",["which","that","who","where"],0,"Extra information about a thing: which, never that."],["People ___ exercise regularly sleep better.",["who","which","whose","where"],0,"People: who."]]},{"id":"t-b1-10","t":"So / Such","s":"so funny, such a funny movie","exp":["<b>so</b> + adjective or adverb: so funny, so fast.","<b>such</b> + (a / an) + adjective + noun: such a funny movie.","Both often continue with <b>that</b>: so tired that…"],"ex":[["The movie was so funny.",""],["It was such a funny movie.",""],["She speaks so fast that I can't understand her.",""],["They are such nice people.",""]],"b":["The test was so easy.","It was such a beautiful day.","He was so tired that he fell asleep.","They have such a big house."],"q":[["It was ___ a long trip.",["such","so","very","too"],0,"Such + a + adjective + noun."],["The food was ___ delicious.",["so","such","such a","so a"],0,"So + adjective."],["She is ___ a good singer.",["such","so","so much","very"],0,"Such + a + adjective + noun."],["I was ___ hungry that I ate two sandwiches.",["so","such","such a","too"],0,"So + adjective + that."],["They are ___ friendly people.",["such","so","such a","so much"],0,"Such + adjective + plural noun."],["The weather was ___ bad that we stayed home.",["so","such","such a","very much"],0,"So + adjective + that."]]}],"writing":[{"id":"w-t-b1-1","t":"Commonly confused words","s":"its / it's · your / you're · their / there / they're","exp":["<b>it's</b> = it is · <b>its</b> = possessive (its tail).","<b>you're</b> = you are · <b>your</b> = possessive.","<b>they're</b> = they are · <b>their</b> = possessive · <b>there</b> = place.","<b>then</b> = after that · <b>than</b> = comparison."],"ex":[["It's cold, and the dog wants its blanket.",""],["You're right about your schedule.",""],["They're leaving their bags over there.",""]],"q":[["Which sentence is correct?",["The company changed its logo.","The company changed it's logo.","The company changed its' logo.","The company changed it is logo."],0,"Possessive: its."],["Which sentence is correct?",["You're going to love this song.","Your going to love this song.","Youre going to love this song.","You're going too love this song."],0,"You are = you're."],["Which sentence is correct?",["They're bringing their friends.","Their bringing there friends.","There bringing their friends.","They're bringing there friends."],0,"They are + possessive."],["Which sentence is correct?",["She's taller than her brother.","She's taller then her brother.","She's more tall than her brother.","She's taller that her brother."],0,"Comparison: than."],["Which sentence is correct?",["We ate, and then we left.","We ate, and than we left.","We ate, and them we left.","We ate, and the we left."],0,"Sequence: then."],["Which sentence is correct?",["Put your phone over there.","Put you're phone over their.","Put your phone over their.","Put you're phone over there."],0,"Possessive your + place there."]]},{"id":"w-t-b1-2","t":"Commas with clauses","s":"although, if, which","exp":["Put a comma after an introductory clause: <b>If it rains, we'll stay home.</b>","No comma when the clause comes second: We'll stay home if it rains.","Non-defining relative clauses go between commas: My phone<b>,</b> which is old<b>,</b> still works.","Use a comma before <b>but</b>, <b>so</b>, <b>and</b> when they join two full sentences."],"ex":[["Although it was late, we kept studying.",""],["We kept studying although it was late.",""],["I was tired, so I went to bed.",""]],"q":[["Which sentence is punctuated correctly?",["If you need help, call me.","If you need help call me.","If, you need help call me.","If you need, help call me."],0,"Comma after the if-clause."],["Which sentence is punctuated correctly?",["Call me if you need help.","Call me, if you need help.","Call me if, you need help.","Call, me if you need help."],0,"If-clause second: no comma."],["Which sentence is punctuated correctly?",["My sister, who lives in Austin, is a nurse.","My sister who lives in Austin, is a nurse.","My sister, who lives in Austin is a nurse.","My sister who, lives in Austin, is a nurse."],0,"Extra information between two commas."],["Which sentence is punctuated correctly?",["It was raining, so we stayed inside.","It was raining so, we stayed inside.","It was, raining so we stayed inside.","It was raining so we, stayed inside."],0,"Comma before so joining two sentences."],["Which sentence is punctuated correctly?",["Although she was tired, she finished the race.","Although she was tired she, finished the race.","Although, she was tired she finished the race.","Although she was, tired she finished the race."],0,"Comma after the introductory clause."],["Which sentence is punctuated correctly?",["The students who studied passed the test.","The students, who studied, passed the test.","The students who studied, passed the test.","The students, who studied passed the test."],0,"Defining clause (only those students): no commas."]]},{"id":"w-t-b1-3","t":"Commonly misspelled words","s":"definitely, separate, necessary","exp":["Some words are misspelled even by native speakers.","Tricks: <b>sep-A-rate</b>, de-FINITE-ly, ne-C-e-SS-ary (one collar, two sleeves).","Also watch: rec<b>ei</b>ve, unt<b>il</b>, begi<b>nn</b>ing, embarra<b>ss</b>, acco<b>mm</b>odate."],"ex":[["I will definitely come.",""],["Keep the files separate.",""],["It's not necessary to bring food.",""]],"q":[["Which word is spelled correctly?",["definitely","definately","definetly","defenitely"],0,"de-FINITE-ly."],["Which word is spelled correctly?",["separate","seperate","separete","seprate"],0,"sep-A-rate."],["Which word is spelled correctly?",["necessary","neccessary","necesary","neccesary"],0,"One c, two s."],["Which word is spelled correctly?",["receive","recieve","receeve","resieve"],0,"e before i after c."],["Which word is spelled correctly?",["beginning","begining","beggining","beginnig"],0,"Double n before -ing."],["Which word is spelled correctly?",["until","untill","untl","untile"],0,"One l."]]}],"phonics":[],"vocab":[{"n":"Technology","w":[["download","descargar"],["update","actualizar"],["password","contraseña"],["screen","pantalla"],["battery","batería"],["charger","cargador"],["settings","configuración"],["device","dispositivo"],["storage","almacenamiento"],["browser","navegador"]]},{"n":"Environment","w":[["pollution","contaminación"],["recycle","reciclar"],["waste","residuos"],["renewable","renovable"],["drought","sequía"],["climate change","cambio climático"],["endangered","en peligro de extinción"],["wildlife","vida silvestre"],["reduce","reducir"],["energy","energía"]]}]},"B1+":{"name":"Intermediate plus","adv":0,"topics":[{"id":"t-b1p-1","t":"Third conditional","s":"Past regrets"},{"id":"t-b1p-2","t":"Mixed conditionals","s":"Past and present"},{"id":"t-b1p-3","t":"Passive: all tenses","s":"has been done, will be done"},{"id":"t-b1p-4","t":"Have something done","s":"Causative"},{"id":"t-b1p-5","t":"Future continuous and perfect","s":"will be doing, will have done"},{"id":"t-b1p-6","t":"Would rather / Had better","s":"Preferences and advice"},{"id":"t-b1p-7","t":"Question tags","s":"Checking information"},{"id":"t-b1p-8","t":"Linking words","s":"although, despite, however"}],"writing":[],"phonics":[],"vocab":[]},"B2":{"name":"Upper intermediate","adv":0,"topics":[{"id":"t-b2-1","t":"Inversion for emphasis","s":"Never have I…"},{"id":"t-b2-2","t":"Modal perfects","s":"should have, might have"},{"id":"t-b2-3","t":"Reporting verbs","s":"suggest, deny, admit"},{"id":"t-b2-4","t":"Participle clauses","s":"Having finished…"},{"id":"t-b2-5","t":"Cleft sentences","s":"What I need is…"},{"id":"t-b2-6","t":"Wish / If only","s":"Regrets"},{"id":"t-b2-7","t":"Emphatic do","s":"I do understand"},{"id":"t-b2-8","t":"Future in the past","s":"was going to, would"}],"writing":[],"phonics":[],"vocab":[]},"C1":{"name":"Advanced","adv":1,"topics":[{"id":"t-c1-1","t":"Advanced inversion","s":"Not only…, Little did…"},{"id":"t-c1-2","t":"The subjunctive","s":"It's vital that he be…"},{"id":"t-c1-3","t":"Nominalization","s":"Academic style"},{"id":"t-c1-4","t":"Ellipsis and substitution","s":"so, do so, one"},{"id":"t-c1-5","t":"Hedging","s":"It would appear that…"},{"id":"t-c1-6","t":"Advanced conditionals","s":"Were you to…, Should you…"}],"writing":[],"phonics":[],"vocab":[]}}};
